extern crate seam_demo;

extern "Rust" {
    // Generated by #[ink::contract] when built with `std`.
    fn __ink_generate_metadata() -> ink::metadata::InkProject;
}

fn main() {
    let project = unsafe { __ink_generate_metadata() };
    println!("{}", serde_json::to_string_pretty(&project).expect("serialize InkProject"));
}
